"""Code-native engineering illustrations; conceptual, never dimensional drawings."""
from math import sin,cos,pi

def assembly_scene():
    def flange(cx,side):
        holes=''.join(f'<ellipse cx="{cx+36*cos(a)}" cy="{240+95*sin(a)}" rx="5" ry="9" class="bolt-hole"/>' for a in [pi/4,3*pi/4,5*pi/4,7*pi/4])
        neck=(f'<path d="M{cx-180} 188H{cx-55}L{cx-16} 152V328L{cx-55} 292H{cx-180}Z" class="machined-body"/><ellipse cx="{cx-180}" cy="240" rx="23" ry="52" class="pipe-end"/><ellipse cx="{cx-180}" cy="240" rx="15" ry="37" class="pipe-bore"/>' if side=='left' else f'<path d="M{cx+12} 152L{cx+55} 188H{cx+180}V292H{cx+55}L{cx+12} 328Z" class="machined-body"/><ellipse cx="{cx+180}" cy="240" rx="23" ry="52" class="pipe-end"/><ellipse cx="{cx+180}" cy="240" rx="15" ry="37" class="pipe-bore"/>')
        return f'<g class="assembly-{side}">{neck}<path d="M{cx-16} 120H{cx}V360H{cx-16}A49 120 0 0 1 {cx-16} 120Z" class="flange-edge"/><ellipse cx="{cx}" cy="240" rx="49" ry="120" class="flange-face"/><ellipse cx="{cx}" cy="240" rx="27" ry="70" class="pipe-bore"/><ellipse cx="{cx}" cy="240" rx="39" ry="102" class="machining-line"/>{holes}</g>'
    return '''<section class="engineering-studio dark" id="engineering-studio"><div class="studio-heading"><div><p class="eyebrow">THE ANATOMY OF A CONNECTION</p><h2>Precision in every part.<br>Strength in the assembly.</h2></div><p>Explore how individual components<br>come together as one connection.</p></div><div class="assembly-stage"><div class="drawing-corner top-left"></div><div class="drawing-corner bottom-right"></div><div class="drawing-meta"><span>CONNECTION STUDY</span><span>CONCEPTUAL ASSEMBLY</span></div><svg class="assembly-svg" viewBox="0 0 1200 480" role="img" aria-label="Conceptual exploded assembly of two steel pipe flanges and a sealing gasket"><defs><linearGradient id="assembly-steel" x1="0" y1="0" x2="0.15" y2="1"><stop offset="0" stop-color="#4d5b65"/><stop offset=".23" stop-color="#c5cdd1"/><stop offset=".29" stop-color="#75858f"/><stop offset=".6" stop-color="#25343f"/><stop offset=".86" stop-color="#80919a"/><stop offset="1" stop-color="#303d47"/></linearGradient><linearGradient id="assembly-face"><stop stop-color="#7a8d97"/><stop offset=".45" stop-color="#b9c6cc"/><stop offset="1" stop-color="#536775"/></linearGradient><linearGradient id="assembly-dark"><stop stop-color="#0b1117"/><stop offset="1" stop-color="#354753"/></linearGradient></defs><g class="drawing-guides" fill="none"><path d="M75 240H1125 M600 55V430"/><path d="M120 104V80H1080V104 M120 375V400H1080V375"/><path d="M110 70L130 90 M1070 390L1090 410"/></g><path class="assembly-flow" d="M100 240H1100"/>'''+flange(350,'left')+'''<g class="assembly-gasket"><ellipse cx="600" cy="240" rx="33" ry="96"/><ellipse cx="600" cy="240" rx="23" ry="72"/><ellipse cx="600" cy="240" rx="29" ry="88"/></g>'''+flange(850,'right')+'''<g class="assembly-callouts"><path d="M350 365V420H220 M600 345V420H665 M850 115V62H980"/><circle cx="350" cy="365" r="3"/><circle cx="600" cy="345" r="3"/><circle cx="850" cy="115" r="3"/><text x="130" y="425">PIPE FLANGE</text><text x="680" y="425">SEALING GASKET</text><text x="990" y="67">MATING FLANGE</text></g></svg><div class="studio-status"><span class="studio-state">Exploded view</span><span>ILLUSTRATION · NOT TO SCALE</span></div></div><div class="studio-toolbar"><div class="assembly-buttons" role="group" aria-label="Assembly view"><button type="button" data-assembly-view="exploded" aria-pressed="true">Exploded view</button><button type="button" data-assembly-view="connected" aria-pressed="false">Assemble connection</button></div><label class="drawing-mode"><input type="checkbox" class="studio-blueprint"> Blueprint view</label><button class="replay-drawing" type="button">Replay drawing</button></div><p class="studio-note">Schematic connection study. Bolting is omitted for clarity; actual geometry and sealing requirements depend on the project specification.</p></section>'''

def hero_drawing():
    ticks=''.join(f'<path d="M{300+252*cos(a):.2f} {300+252*sin(a):.2f}L{300+(244 if i%5 else 233)*cos(a):.2f} {300+(244 if i%5 else 233)*sin(a):.2f}"/>' for i in range(60) for a in [i*pi/30])
    return '<svg class="hero-engineering" viewBox="0 0 600 600" aria-hidden="true"><g class="hero-orbit"><circle cx="300" cy="300" r="250"/><circle cx="300" cy="300" r="220"/>'+ticks+'<path class="orbit-accent" d="M300 50A250 250 0 0 1 550 300"/></g><path class="hero-axis" d="M20 300H110 M490 300H580 M300 20V110 M300 490V580"/></svg>'

