def product_drawing(i):
    paths=[
      '<path d="M100 130H290 M100 270H290 M100 155H290 M100 245H290"/><ellipse cx="100" cy="200" rx="28" ry="70"/><ellipse cx="100" cy="200" rx="17" ry="45"/><ellipse cx="290" cy="200" rx="28" ry="70"/><ellipse cx="290" cy="200" rx="17" ry="45"/>',
      '<circle cx="200" cy="200" r="110"/><circle cx="200" cy="200" r="65"/><circle cx="200" cy="200" r="45"/>'+''.join(f'<circle cx="{200+88*cos(a)}" cy="{200+88*sin(a)}" r="9"/>' for a in [i*pi/4 for i in range(8)]),
      '<path d="M80 280V200Q80 90 190 90H270V160H190Q150 160 150 200V280Z M70 265H160 M255 80V170"/><path d="M115 300V200Q115 125 190 125H290" class="drawing-center"/>',
      '<path d="M65 185H140L185 145H215L260 185H335V255H260L215 285H185L140 255H65Z M200 145V75 M150 75H250 M155 62H245V88H155Z M150 185L250 255 M150 255L250 185 M85 170V270 M315 170V270"/>',
      '<path d="M80 180H290V220H80Z M65 170H95V230H65Z M280 160H315L335 200 315 240H280L260 200Z"/>'+''.join(f'<path d="M{x} 180L{x-15} 220"/>' for x in range(115,275,15)),
      '<circle cx="200" cy="200" r="110"/><circle cx="200" cy="200" r="73"/>'+''.join(f'<circle cx="200" cy="200" r="{r}"/>' for r in range(79,108,5)),
      '<path d="M60 140H85V260H60Z M315 140H340V260H315Z M85 165H115 M85 235H115 M285 165H315 M285 235H315"/>'+''.join(f'<path d="M{x} 165Q{x+10} 130 {x+20} 165V235Q{x+10} 270 {x} 235Z"/>' for x in range(115,285,20)),
      '<path d="M60 130H85V270H60Z M315 130H340V270H315Z M85 165H190V235H85 M190 150H230V250H190Z M230 165H315 M230 235H315 M50 145H350 M50 255H350 M120 135V155 M280 135V155 M120 245V265 M280 245V265"/>'
    ][i]
    return '<svg viewBox="0 0 400 400"><g class="product-outline">'+paths+'</g><g class="dimension-lines"><path d="M40 200H360 M200 40V360 M65 310V330H335V310 M55 320L75 340 M325 320L345 340"/></g></svg>'
